303	async function HandleClientMessage(
304	  socket: WebSocket,
305	  client: ConnectedClient,
306	  params: ChatWebSocketConnectParams,
307	  context: ChatWebSocketContext,
308	  broadcaster: Awaited<ReturnType<SessionBroadcasterRegistry["GetOrCreate"]>>,
309	  data: WebSocket.RawData,
310	): Promise<void>
311	{
312	  let parsed: unknown;
313	
314	  try
315	  {
316	    parsed = JSON.parse(data.toString());
317	  }
318	  catch
319	  {
320	    SendErrorFrame(socket, params, "invalid_frame", "malformed JSON frame", false);
321	    return;
322	  }
323	
324	  let frame;
325	
326	  try
327	  {
328	    frame = ParseClientFrame(parsed);
329	  }
330	  catch (error)
331	  {
332	    const message = error instanceof Error ? error.message : String(error);
333	    const code = error instanceof StorageError ? error.code : "invalid_frame";
334	    SendErrorFrame(socket, params, code, message, false);
335	    return;
336	  }
337	
338	  if (frame.frame.pile !== params.pile || frame.frame.sessionId !== params.sessionId)
339	  {
340	    SendErrorFrame(
341	      socket,
342	      params,
343	      "invalid_frame",
344	      "frame pile/sessionId does not match connection",
345	      false,
346	      frame.frame.id,
347	    );
348	    return;
349	  }
350	
351	  const key = {
352	    pile: params.pile,
353	    sessionId: params.sessionId,
354	  };
355	
356	  try
357	  {
358	    switch (frame.kind)
359	    {
360	      case x_clientHelloKind:
361	        break;
362	
363	      case x_clientUserMessageKind:
364	        await broadcaster.HandleUserMessage(client.connectionId, frame.payload);
365	        break;
366	
367	      case x_clientHistoryRequestKind:
368	        await broadcaster.HandleHistoryRequest(
369	          client.connectionId,
370	          frame.frame.id,
371	          frame.payload,
372	        );
373	        break;
374	
375	      case x_clientModelSelectKind:
376	        await context.agentManager.selectModel(
377	          key,
378	          ToModelReference(frame.payload),
379	          frame.payload.applyTo ?? "next_turn",
380	        );
381	        break;
382	
383	      case x_clientAckKind:
384	        broadcaster.RecordAck(client.connectionId, frame.payload.sequence);
385	        break;
386	
387	      case x_clientCancelKind:
388	      case x_clientStopGeneratingKind:
389	        await context.agentManager.cancelTurn(key);
390	        break;
391	
392	      case x_clientPingKind:
393	      {
394	        const pong = CreateChatEnvelope({
395	          kind: x_serverPongKind,
396	          pile: params.pile,
397	          sessionId: params.sessionId,
398	          clientId: params.clientId,
399	          payload: {
400	            requestId: frame.frame.id,
401	          },
402	        });
403	        socket.send(JSON.stringify(pong));
404	        break;
405	      }
406	    }
407	  }
408	  catch (error)
409	  {
410	    const message = error instanceof Error ? error.message : String(error);
411	    const code = error instanceof StorageError ? error.code : "request_failed";
412	    SendErrorFrame(socket, params, code, message, false, frame.frame.id);
413	  }
414	}
415	
416	export async function ResolveChatWebSocketUpgrade(
417	  context: ChatWebSocketContext,
418	  request: IncomingMessage,
419	): Promise<ChatWebSocketConnectParams | null>
420	{
421	  const url = new URL(request.url ?? "/", `http://${request.headers.host ?? "localhost"}`);
422	
423	  if (!MatchChatWebSocketPath(url.pathname))
424	  {
425	    return null;
426	  }
427	
428	  try
429	  {
430	    const params = ParseChatWebSocketQuery(url);
431	    await ValidateChatWebSocketConnect(context, params);
432	    return params;
433	  }
434	  catch (error)
435	  {
436	    if (error instanceof StorageError)
437	    {
438	      throw error;
439	    }
440	
441	    throw new StorageError(
442	      "invalid_request",
443	      error instanceof Error ? error.message : String(error),
444	    );
445	  }
446	}
447	
448	export function StorageErrorToHttpStatus(error: StorageError): number
449	{
450	  switch (error.code)
451	  {
452	    case "not_found":
453	      return 404;
454	
455	    case "invalid_pile":
456	    case "invalid_session_id":
457	    case "invalid_request":
458	    case "invalid_history_request":
459	      return 400;
460	
461	    default:
462	      return 400;
463	  }
464	}
